type Tree = Option<Box<Node>>;
struct Node {
    value: i32,
    left: Tree,
    right: Tree,
}
fn node(value: i32, left: Tree, right: Tree) -> Tree {
    Some(Box::new(Node { value, left, right }))
}

fn serialize(root: &Tree) -> String {
    fn visit(root: &Tree, out: &mut Vec<String>) {
        match root {
            None => out.push("#".into()),
            Some(n) => {
                out.push(n.value.to_string());
                visit(&n.left, out);
                visit(&n.right, out);
            }
        }
    }
    let mut out = Vec::new();
    visit(root, &mut out);
    out.join(",")
}
fn deserialize(text: &str) -> Tree {
    // Tokens arrive in the same preorder, so each # closes exactly one child.
    fn build<'a>(tokens: &mut impl Iterator<Item = &'a str>) -> Tree {
        match tokens.next() {
            None | Some("#") => None,
            Some(token) => {
                let value = token.parse().unwrap();
                let left = build(tokens);
                let right = build(tokens);
                node(value, left, right)
            }
        }
    }
    build(&mut text.split(','))
}
fn round_trip(root: &Tree) -> String {
    let text = serialize(root);
    assert_eq!(serialize(&deserialize(&text)), text);
    text
}
fn inorder_values(root: &Tree) -> Vec<i32> {
    match root {
        None => Vec::new(),
        Some(n) => {
            let mut out = inorder_values(&n.left);
            out.push(n.value);
            out.extend(inorder_values(&n.right));
            out
        }
    }
}

fn main() {
    let result = round_trip(&node(1, None, None));
    println!("{result}");
}

